--- a/ts/src/fetch.ts
+++ b/ts/src/fetch.ts
@@ -7,36 +7,84 @@ export class HttpError extends Error {
   }
 }

 export class TimeoutError extends Error {
   constructor(public readonly url: string, public readonly timeoutMs: number) {
     super(`timed out after ${timeoutMs}ms fetching ${url}`);
     this.name = "TimeoutError";
   }
 }

+/** Decides whether, and after how long, a failed attempt is tried again. */
+export interface RetryStrategy {
+  /** Return the delay in ms before retrying `attempt` (1-based), or null to give up. */
+  delayBefore(attempt: number, err: unknown): number | null;
+}
+
+export const noRetry: RetryStrategy = { delayBefore: () => null };
+
+/** Retry up to `times` on TimeoutError or 5xx, waiting `delayMs` each time. */
+export function fixedRetry(times: number, delayMs = 0): RetryStrategy {
+  return {
+    delayBefore: (attempt, err) => (attempt <= times && isTransient(err) ? delayMs : null),
+  };
+}
+
+/** Retry up to `times` on TimeoutError or 5xx, doubling the delay from `baseMs`. */
+export function exponentialBackoff(times: number, baseMs = 100): RetryStrategy {
+  return {
+    delayBefore: (attempt, err) =>
+      attempt <= times && isTransient(err) ? baseMs * 2 ** (attempt - 1) : null,
+  };
+}
+
+function isTransient(err: unknown): boolean {
+  return err instanceof TimeoutError || (err instanceof HttpError && err.status >= 500);
+}
+
 export interface FetchOptions {
   timeoutMs?: number;
   headers?: Record<string, string>;
+  /** Defaults to noRetry, so existing callers see no change. */
+  retry?: RetryStrategy;
 }

 const DEFAULT_TIMEOUT_MS = 5000;

+const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
+
 export async function fetchJson<T>(url: string, opts: FetchOptions = {}): Promise<T> {
+  const retry = opts.retry ?? noRetry;
+  for (let attempt = 1; ; attempt++) {
+    try {
+      return await fetchOnce<T>(url, opts);
+    } catch (err) {
+      const delay = retry.delayBefore(attempt, err);
+      if (delay === null) {
+        throw err;
+      }
+      if (delay > 0) {
+        await sleep(delay);
+      }
+    }
+  }
+}
+
+async function fetchOnce<T>(url: string, opts: FetchOptions): Promise<T> {
   const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
   const controller = new AbortController();
   const timer = setTimeout(() => controller.abort(), timeoutMs);
   try {
     const res = await fetch(url, { signal: controller.signal, headers: opts.headers });
     if (!res.ok) {
       throw new HttpError(res.status, url);
     }
     return (await res.json()) as T;
   } catch (err) {
     if ((err as Error).name === "AbortError") {
       throw new TimeoutError(url, timeoutMs);
     }
     throw err;
   } finally {
     clearTimeout(timer);
   }
 }
